// Auto-generated Smooth Dune Heightmap Elevation LUT (256x256)
// Generated from user-provided dune imagery with smooth periodic boundaries

const B64_LUT = "";

let _lut = null;

export function getDuneElevationLUT() {
    if (_lut) return _lut;
    const binStr = atob(B64_LUT);
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binStr.charCodeAt(i);
    }
    _lut = bytes;
    return _lut;
}
